List<String> separateParenGroups(String parenString) {
  if (parenString.isEmpty || !isValidParen(parenString)) return [];
  int depth = 0;
  List<String> groups = [];
  StringBuffer current = StringBuffer();

  for (char ch in parenString.characters) {

    if (ch == '(') {
      depth++;
      current.write(ch);
    } else if (ch == ')') {
      depth--;

      if (depth < 0) {
        throw ArgumentError('Unbalanced parentheses at position ${parenString.indexOf(ch)}');
      }


      if (depth == 0) {
        groups.add(current.toString());
        current.clear();
      } else {
        current.write(ch);
      }
    }
  }

  if (current.isNotEmpty) {
    throw ArgumentError('Incomplete group found.');
  }

  return groups;
}



bool isValidParen(String s) {
  int count = 0;
  for (var c in s) {
    if (c == '(') count++;
    else if (c == ')') count--;
    if (count < 0) return false;
  }
  return count == 0 && s.isNotEmpty;
}

