double truncateNumber(double number) {
  if (number.isNegative && !number.hasFiniteFractionalPart()) return -1;

  final rounded = double.round(number);
  if (rounded == 0 || rounded == -1.0) return 0;

  final fractional = number - rounded.toDouble();
  return (fractional < 0 ? fractional + 1 : fractional).abs();
}

