  List<List<int>> groups = [];


  int i = 0;
  while (i < parenString.length) {
    if (parenString[i] == '(') {

      int depth = 1;
      int j = i + 1;
      while (j < parenString.length && depth > 0) {
        if (parenString[j] == '(') depth++;
        else if (parenString[j] == ')') depth--;

        j++;
      }

      String groupContent = parenString.substring(i, j);
      if (groupContent.isNotEmpty && 
          !groups.any((g) => g.join() == groupContent)) {
        groups.add([groupContent]);
      }
      i = j - 1;
    } else {
      i++;
    }
  }



  List<int> result = [];
  for (var group in groups) {
    final contentStr = group.first;

    RegExp balancedGroupRegex = RegExp(r'^$$.*?$$$', dotAll: true);


    Match? match = balancedGroupRegex.firstMatch(contentStr.trim());
    if (match != null) {

      int n = match.group(2)?.length ?? 0;
      result.add(n);
    } else {

      result.add(-1); 
    }
  }

  return result;
}

