class Solution {
  int parseNestedParens(String s) {
    final List<int> counts = <int>[];

    for (var i = 0, level = 0; i < s.length; ++i) {
      if (s[i] == '(') {
        if (level > 0) {
          // Inside a group: count the length of this sub-group.
          counts.add(i - level); 
        }
        ++level;
      } else if (s[i] == ')') {
        --level;
      }
    }

    return counts.isEmpty ? [counts.length] : counts;
  }
}

