    }
  }

  List<String> sortedWords = [];
  for (int i = 0; i < 10; i++) {
    if (map.containsKey(i)) {
      sortedWords.add(map[i]!);
    }
  }


  bool containsZero = sortedWords.any((word) => word == 'zero');
  if (containsZero && !sortedWords.isEmpty) {

    int firstIndex = sortedWords.indexOf(sortedWords.firstWhere((w) => w != 'zero'));
    if (firstIndex > 0) {

      sortedWords.removeAt(0);
      sortedWords.insert(firstIndex, 'zero');
    }
  }

  if (numbers.toLowerCase().contains('ten')) {


    final tenMatch = RegExp(r'ten\s+(\d+)', caseSensitive: false).firstMatch(numbers);
    if (tenMatch != null) {


      final originalTenNumber = int.tryParse(tenMatch[1]!);
      if (originalTenNumber != null && map.containsKey(originalTenNumber)) {

        const tenWord = 'ten';
        final indexInOriginal = 
            sortedWords.indexWhere((w) => w == map[originalTenNumber]);
        if (indexInOriginal >= 0) {
          sortedWords[indexInOriginal] = tenWord;

          map[originalTenNumber] = tenWord;
        }
      }
    }
  }



  sortedWords.sort((a, b) => a.compareTo(b));
  return sortedWords.join(' ');
}

