  void carRacingSimulation(int iterations) {

    List<List<double>> positions = [];


    for (int iter = 0; iter < iterations; iter++) {

      var posList = raceCars.map((id) => randomOffset(10)).toList();


      if (!positions.contains(posList)) {
        positions.add(posList);

        if (positions.length >= 5) break;
      }
    }


    print('\nCARS RACE SIMULATION ($iterations ITERATIONS):');
    print('=' * 60);


    bool firstRun = true;


    while (true) {

      print(formatPosition(-999, -1)); 


      for (var idx = 0; idx < positions.length && idx < 5; idx++) {
        final simPos = positions[idx].map((p) => p).toList(); 

        for (final pos in simPos) {
          print(formatPosition(pos, idx));
        }

        if (!firstRun) {

          print('-' * 60);
        } else {
          firstRun = false;
        }
      }


      if (!firstRun || !input('Continue simulation? ').toLowerCase().startsWith('y')) {
        break;
      }
    }


    print('\nRESULTS SUMMARY:');
    print('Total Distances Covered: $totalDistances units');
    print('Simulations Run: $iterations');
  }


