    late Set<int> distinct; 
    bool done = false;     
    while (!done && (distinct == null || distinct.length < lst.length)) {
      if (distinct == null) distinct = {};

      for (int i = 0, n = distinct?.length ?? 0; i < n; ++i) {
        final v = rng.nextInt(lst.length);   
        if (v >= 0 && v < lst.length && !distinct!.contains(v)) {
          distinct!.add(v);

          if (distinct!.length == lst.length) {
