  for (int i = 0; i < 10; i++) {
    int cnt = occurrences[i];
    if (cnt > 0) {

      if (!firstDigitPrinted) {
        output += "$i:$cnt ";
        firstDigitPrinted = true;
      } else {
        output += ', $i:$cnt ';
      }
    }
  }


