import 'dart:collection';

int smallestChange(List<int> arr) {
  int n = arr.length;
  List<List<bool>> dp = List.generate(n + 1, (_) => List.filled(arr.length + 1, true));

  for (int i = 0; i <= n; ++i) {
    dp[i][arr.length] = false; 
  }

  for (int s = 0; s < pow(2, n).toInt(); ++s) {
    int sum = 0;
    for (int j = 0; j < n; ++j) {
      if ((s >> j & 1) != 0) sum += arr[j];
    }

    for (int i = 1; i <= n; ++i) {
      if (sum == 0 && i == 0) dp[0][n - i] = true;
      else dp[i][n - i] = false;

      for (int k = 0; k < i; ++k) {
        if ((dp[k][(s >> k & 1) == 0 ? n - i : n - i - 1]) || 
            (k > 0 && dp[k-1][(s >> (k-1) & 1) == 0 ? n - i : n - i - 1])) {
          dp[i][n-i] = true;
          break;
        }
      }
    }

    if (dp[n].indexOf(true) >= 0) return dp[n].firstWhere((bool b) => b);
  }

  throw Exception('No partition found');
}

