  class Heap<T extends Comparable<T>> {
    final List<T?> _data = [];
    int get size => _data.where((e) => e != null).length;

    void add(T value) {
      _data.add(value);
      _bubbleUp(size - 1);
    }

    bool isEmpty => size == 0;

    T remove() {
      if (_data.isEmpty || _data.last == null) throw StateError('Empty heap');

      T? smallest = _min();
      _swap(0, _data.length - 1);
