    void _swap(int i, int j) {
      final temp = _data[i];
      _data[i] = _data[j];
      _data[j] = temp;
    }

    void _sinkDown(int index) {
      int parentIndex = index;
      int childIndex = (parentIndex + 1) * 2 - 1;
      while (childIndex < _data.length && _data[parentIndex!]?.compareTo(_data[childIndex]!) > 0) {
        if ((childIndex + 1) < _data.length &&
