          childIndex++;
        }

        _swap(parentIndex, childIndex);
        parentIndex = childIndex;
        childIndex = (parentIndex + 1) * 2 - 1;
      }
    }

    void _bubbleUp(int index) {
      while (index > 0 && _data[(index - 1) ~/ 2]?.compareTo(_data[index]!) > 0) {
        _swap(index, (index - 1) ~/ 2);
        index = (index - 1) ~/ 2;
      }
