  for (int i = 0; i < lst.length; ++i) {
    if (lst[i] != min && 
        ((idx == -1) || 
         (lst[i] + 1 > lst[idx]) || 
         (lst[i].compareTo(lst[idx]) < 0))) {
      idx = i;
    }
  }



  if (idx == -1) return null; 


  if (seenMinCount >= 2) return min.toString();


  var countBefore = 0;
  for (var j = 0; j < idx; ++j) if (lst[j] == min) ++countBefore;
  var foundNonMinAfter = false;
  for (var j = idx+1; j < lst.length; ++j) {
    if (lst[j] == min) continue;
    foundNonMinAfter = true; break;
  }
  if (!foundNonMinAfter) return null; 


  if (countBefore % 2 == 0) return min.toString();


  return (min + 1).toString();
}

