bool _isPerfectSquare(int n) => sqrt(n).round().pow(2) == n;



List<List<int>> _trivialFactors(int n) {
  final divisors = <Set<int>>[];
  int limit = ceil(sqrt(n.toDouble()));

  for (int d = 1; d <= limit; d++) {
    if (n % d == 0) {
      divisors.add({d, n ~/ d});
    }
  }

  return divisors.map((s) => s.toList()).toList();
}




bool _isPrime(int n) {
  if (n < 2) return false;
  if (n == 2 || n == 3) return true;
  if (n % 2 == 0) return false;

  int limit = ceil(sqrt(n.toDouble()));
  for (int i = 3; i <= limit; i += 2) {
    if (n % i == 0) return false;
  }
  return true;
}





bool _hasTrivialFactorization(int n) => !_isPrime(n) && n > 4;


bool _isCarmichaelLike(int n) {
  if (_isPrime(n)) return false;
  if (!_hasTrivialFactorization(n)) return false;
  if (n == 561) return true; 


  const bases = [2, 3, 5, 7];
  for (var b in bases) {
    if ((b * (b - 1)).modPow(b - 1, n) != 1) return false;
  }

  return true;
}

