int maxFill(List<List<int>> grid, int capacity) {

  final nRows = grid.length;
  if (nRows == 0) return 0;
  final nCols = grid[0].length;
  if (nCols == 0) return 0;


  final totalCapacity = nRows * nCols;
  if (capacity >= totalCapacity) return totalCapacity;
  if (grid.every((row) => row.every((v) => v == 1))) return totalCapacity;


  int filled = 0;
  for (var i = 0; i < nRows; ++i) {
    var rowHasZero = false;
    for (var j = 0; j < nCols; ++j) {
      if (grid[i][j] == 0) {
        rowHasZero = true;
        break;
      }
    }
    if (!rowHasZero) continue; 
    filled += 1;
  }


  return min(filled + 1, capacity);
}

