List<int> sortArray(List<int> arr) {

  if (arr.length <= 1) return arr;



  int pivotIndex = arr.length ~/ 2; 
  int pivot = arr[pivotIndex];


  List<int> left = [];
  List<int> right = [];


  for (int i = 0; i < arr.length; i++) {
    if (i == pivotIndex) continue; 
    if (arr[i] > pivot) {
      left.add(arr[i]);
    } else {
      right.add(arr[i]);
    }
  }


  return sortArray(left).addAll([pivot], sortArray(right));
}

