    for (int i = 0; i <= n; i++) {
      dp[i][i] = 0; 

      for (int j = 0; j < i - 1; j++) {
        if (dp[j][i - 1] != null && dp[j + 1][i] != null) {
          dp[j][i] = dp[j][i - 1]! + dp[j + 1][i]!;

