        var sol = List.filled(i + 1, 0);
        solveHelper(0, i, dp, sol);
        print(sol);
      }
    }
  }


  void solveHelper(int left, int right, List<List<int>> dp, List<int> path) {
    if (left == right) {
      path[left]++;
      return;
    }


    for (var v in [2, 3]) {
      int p = pow(v, double.tryParse(path[left].toString()) ?? 0).toInt();
      int q = pow(v, double.tryParse(path[right].toString()) ?? 0).toInt();
      if ((p * q)! > dp[left][right]!) continue;

      path[left] += 1;
      solveHelper(left + 1, right - 1, dp, path);
      path[left] -= 1;
    }
  }


  print("Solutions for each N from 1 to $maxN:");
  for (int n = 1; n <= maxN; n++) {
    print("\nFor $n :");
    solve(n);
  }
}

