  for (final number in arr) {
    if (number >= 0 && number < n && isPrime[number]) {
      primeSet.add(number);
    }
  }

  final primes = primeSet.toList();
  int countPrimes = primes.length; 


  if ((countPrimes & 1) == 1) { 
    return -1;
  }

  List<List<int>> dp = List.generate(countPrimes + 1, (_) => []);
  dp[0].add(0);

  for (int pIdx = 0; pIdx < countPrimes; pIdx++) {
    for (int subLen = dp[pIdx].length - 1; subLen >= 0; subLen--) {

      int remaining = primes[pIdx];
      bool valid = true;

      while (remaining > 0) {
        int nextPrimeIndex = binarySearch(primes, remaining + 1);

        if (nextPrimeIndex >= countPrimes || nextPrimeIndex == pIdx) {
          valid = false;
          break;
        }
        if (!dp[subLen + 1].contains(nextPrimeIndex)) {
          valid = false;
          break;
        }
        remaining -= primes[nextPrimeIndex];
      }

      if (valid) {
        dp[subLen + 1].addAll(dp[subLen]);
      }
    }
  }

  return dp[countPrimes].isEmpty ? -1 : dp[countPrimes][0];
}


List<int> binarySearch(List<int> list, int target) {
  int low = 0, high = list.length - 1;
  while (low <= high) {
    int mid = (low + high) >> 1;
    if (list[mid] == target) return mid;
    else if (list[mid] < target) low = mid + 1;
    else high = mid - 1;
  }
  return low;
}

