      listA.add(candidate);
      dict[candidate]--;
      sum += candidate.length;
    } else {


      var remaining = [for (var pair in dict.entries)..removeWhere((e) => e.value == 0)];
      List<String> newList = [];
      for (var entry in remaining) {
