        String word = '';
        for (int j = 0; j < avgLength; j++) {
          int idx = i + j;

          if (idx >= newList.length) break;
          word += newList[idx];
        }
        newList.removeAt(newList.indexOf(word));
      }
      return newList;
    }
  }


  return listA;
}

