int _levenshtein(String a, String b) {
  final n = a.length + 1;
  final m = b.length + 1;
  List<int> prev = List.filled(m, -1)..[0] = 0;
  List<int> curr = List.filled(m, -1);

  for (int j = 0; j < m; ++j) prev[j] = j;

  for (int i = 1; i <= n; ++i) {
    curr.fillRange(0, m, i);
    for (int j = 1; j < m; ++j) {
