    if (ch >= 'a' && ch <= 'z') {
      reversed += ((char)(ch + ('A' - 'a'))).toString(); 
    } else if (ch >= 'A' && ch <= 'Z') {
      reversed += ((char)(ch + ('a' - 'A'))).toString(); 
    } else {

      reversed += ch.toString();
    }

  }
  return reversed;
}

