  String _solve(String input) {
    if (input.isEmpty || input.length == 1) return input;


    int len = input.length;
    bool isPalindrome(int l, int r) {
      while (l < r && input[l] == input[r]) {
        l++;
        r--;
      }
      return l >= r;
    }



    List<int> dp = List.filled(len + 1, -1); 



    for (int i = 0; i <= len; i++) {
      dp[i] = i; 
    }


    for (int length = 2; length <= len; length++) {
      for (int start = 0; start <= len - length; start++) {
        int end = start + length - 1;
        if (isPalindrome(start, end)) {
          dp[end] = min(dp[end], dp[start - 1]);
        } else {

          for (int k = max(0, start + dp[start]); k <= min(end - 1, len - dp[end]); k++) {
            dp[end] = min(dp[end], dp[k] + dp[k + 1] - 1);
          }
        }

      }
    }


    return "DP[$dp[$len]]"; 
